      slide.makeTranslation(0, -(1 - k) * 420, 0);
      place.makeTranslation(0, 0, -d).multiply(scl.makeScale(px, px, px)).multiply(slide);
      frame.matrixWorld.multiplyMatrices(cam.matrixWorld, place);
